import React, { useState, useEffect } from 'react';
import { useAuth } from '../contexts/AuthContext';
import axios from 'axios';

const MyBookings = () => {
  const { user, token, loading: authLoading } = useAuth();
  const [bookings, setBookings] = useState([]);
  const [loading, setLoading] = useState(true);
  const [carDetailsById, setCarDetailsById] = useState({});

  useEffect(() => {
    if (!authLoading && user && user.role === 'USER') {
      fetchBookings();
    }
  }, [user, authLoading]);

  const fetchBookings = async () => {
    try {
      const response = await axios.get('http://localhost:8082/api/bookings/user/my-bookings', {
        headers: token ? { Authorization: `Bearer ${token}` } : undefined
      });
      const bookingList = response.data || [];
      setBookings(bookingList);

      const uniqueCarIds = Array.from(new Set(bookingList.map(b => b.carId).filter(Boolean)));
      if (uniqueCarIds.length > 0) {
        await fetchCarDetails(uniqueCarIds);
      }
    } catch (error) {
      console.error('Error fetching bookings:', error);
    } finally {
      setLoading(false);
    }
  };

  const fetchCarDetails = async (carIds) => {
    try {
      const requests = carIds.map(id =>
        axios.get(`http://localhost:8081/api/cars/public/${id}`)
          .then(res => ({ id, data: res.data }))
          .catch(() => ({ id, data: null }))
      );
      const results = await Promise.all(requests);
      const map = {};
      results.forEach(({ id, data }) => {
        if (data) {
          map[id] = data;
        }
      });
      setCarDetailsById(prev => ({ ...prev, ...map }));
    } catch (e) {
      console.error('Error fetching car details:', e);
    }
  };

  const handleCancelBooking = async (bookingId) => {
    if (window.confirm('Are you sure you want to cancel this booking?')) {
      try {
        await axios.delete(`http://localhost:8082/api/bookings/user/${bookingId}`);
        setBookings(bookings.filter(booking => booking.id !== bookingId));
      } catch (error) {
        console.error('Error canceling booking:', error);
      }
    }
  };

  if (!user || user.role !== 'USER') {
    return (
      <div style={styles.container}>
        <div style={styles.emptyState}>
          <h2>Access Denied</h2>
          <p>You need to be logged in as a user to view bookings.</p>
        </div>
      </div>
    );
  }

  if (loading) {
    return (
      <div style={styles.container}>
        <div style={styles.emptyState}>
          <h2>Loading your bookings...</h2>
        </div>
      </div>
    );
  }

  return (
    <div style={styles.container}>
      <h2 style={styles.title}>My Bookings</h2>

      {bookings.length === 0 ? (
        <div style={styles.emptyState}>
          <h3>No bookings found</h3>
          <p>You haven't made any bookings yet.</p>
        </div>
      ) : (
        <div style={styles.grid}>
          {bookings.map(booking => (
            <div key={booking.id} style={styles.card}>
              {carDetailsById[booking.carId]?.imageUrl && (
                <img
                  src={carDetailsById[booking.carId].imageUrl}
                  alt={carDetailsById[booking.carId].name || `Car ${booking.carId}`}
                  style={styles.image}
                />
              )}
              <h3 style={styles.carName}>
                {carDetailsById[booking.carId]?.name || `Booking #${booking.id}`}
              </h3>
              <div style={styles.info}>
                {!carDetailsById[booking.carId]?.name && (
                  <p><strong>Car ID:</strong> {booking.carId}</p>
                )}
                <p><strong>Start Date:</strong> {new Date(booking.startDate).toLocaleDateString()}</p>
                <p><strong>End Date:</strong> {new Date(booking.endDate).toLocaleDateString()}</p>
                <p><strong>Total Amount:</strong> ${booking.totalAmount}</p>
                <p>
                  <strong>Status:</strong>
                  <span style={{
                    color: booking.status === 'CONFIRMED' ? 'green' :
                           booking.status === 'PENDING' ? 'orange' : 'red',
                    fontWeight: 'bold',
                    marginLeft: 6
                  }}>
                    {booking.status}
                  </span>
                </p>
                {booking.notes && <p><strong>Notes:</strong> {booking.notes}</p>}
                <p><strong>Created:</strong> {new Date(booking.createdAt).toLocaleDateString()}</p>
              </div>

              {booking.status === 'PENDING' && (
                <button
                  onClick={() => handleCancelBooking(booking.id)}
                  style={styles.cancelButton}
                >
                  Cancel Booking
                </button>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

// CSS-in-JS Styles
const styles = {
  container: {
    padding: '2rem',
    maxWidth: '1200px',
    margin: '0 auto',
    fontFamily: "'Segoe UI', Tahoma, Geneva, Verdana, sans-serif",
  },
  title: {
    fontSize: '2rem',
    fontWeight: '600',
    marginBottom: '1.5rem',
    textAlign: 'center',
    color: '#2c3e50'
  },
  grid: {
    display: 'grid',
    gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))',
    gap: '1.5rem',
  },
  card: {
    background: '#fff',
    borderRadius: '12px',
    padding: '1.5rem',
    boxShadow: '0 4px 12px rgba(0,0,0,0.08)',
    transition: 'transform 0.2s ease, box-shadow 0.2s ease',
  },
  image: {
    width: '100%',
    height: '180px',
    objectFit: 'cover',
    borderRadius: '10px',
    marginBottom: '1rem',
  },
  carName: {
    fontSize: '1.2rem',
    fontWeight: '600',
    color: '#34495e',
    marginBottom: '0.5rem'
  },
  info: {
    fontSize: '0.95rem',
    color: '#555',
    lineHeight: '1.5',
  },
  cancelButton: {
    marginTop: '1rem',
    padding: '0.6rem 1rem',
    backgroundColor: '#e74c3c',
    border: 'none',
    borderRadius: '8px',
    color: '#fff',
    cursor: 'pointer',
    fontSize: '0.9rem',
    fontWeight: '600',
    transition: 'background 0.3s ease',
  },
  emptyState: {
    textAlign: 'center',
    padding: '2rem',
    color: '#777'
  }
};

export default MyBookings;
